import{_ as o,o as t,c as d,ag as c}from"./chunks/framework.BaNuf0sO.js";const h=JSON.parse('{"title":"MenuTree（树形菜单）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/core/src/components/menu/docs/README-MenuTree.md","filePath":"docs/core/src/components/menu/docs/README-MenuTree.md"}'),a={name:"docs/core/src/components/menu/docs/README-MenuTree.md"};function r(s,e,l,n,i,u){return t(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="menutree-树形菜单" tabindex="-1">MenuTree（树形菜单） <a class="header-anchor" href="#menutree-树形菜单" aria-label="Permalink to &quot;MenuTree（树形菜单）&quot;">​</a></h1><blockquote><p>基于 ElMenu 的配置化菜单：menus 树形数据递归渲染，含**树形（手风琴）/ 分组（section heading）**双形态；routerMode 路由联动、autoClose 选中收合、collapse 折叠透传。 范式页：真实消费方为 <code>AppSidebar</code>（packages/core/src/components/app-layout/AppSidebar.vue）；菜单数据契约范式见 <code>apps/reference/src/router/modules/test.ts</code></p></blockquote><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><ul><li><strong>何时用</strong>：侧栏 / 导航需要配置驱动的菜单（递归子菜单、路由联动、折叠态、分组标题）</li><li><strong>何时不用</strong>：单层 / 少量菜单直接用 ElMenu；菜单数据不来自路由配置时自行组装数据再接入</li><li>数据驱动：<code>menus</code> 树形节点含 <code>children</code> 递归出父级容器，叶子渲染 <code>ElMenuItem</code>；<code>menuFlatList</code> 拍平列表供 autoClose 沿 <code>parentPath</code> 递归算父链</li><li><strong>双形态</strong>：<code>groupMode=false</code>（默认）父级 → <code>ElSubMenu</code> 手风琴；<code>groupMode=true</code> 父级 → <code>ElMenuItemGroup</code> 分组标题（详见下节）</li><li>增强点：routerMode（defaultActive 取 route.path + ElMenu :router）、autoClose（选中一项收合其它展开子菜单）、collapse 透传、ElMenu 其余 attrs 整包透传、open / close expose</li></ul><h2 id="树形-分组双形态-groupmode" tabindex="-1">树形 / 分组双形态（<code>groupMode</code>） <a class="header-anchor" href="#树形-分组双形态-groupmode" aria-label="Permalink to &quot;树形 / 分组双形态（`groupMode`）&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th><code>groupMode=false</code>（默认，树形）</th><th><code>groupMode=true</code>（分组）</th></tr></thead><tbody><tr><td>L1 有子项</td><td><code>ElSubMenu</code>，可点击展开 / 收起，<strong>默认收起</strong></td><td><code>ElMenuItemGroup :title</code>，小字号 + 弱色，<strong>不可点、不导航、不折叠</strong></td></tr><tr><td>L1 叶子</td><td><code>ElMenuItem</code></td><td><code>ElMenuItem</code>（同左）</td></tr><tr><td>L2 及更深有子项</td><td><code>MenuItemSub</code> 递归 <code>ElSubMenu</code></td><td><strong>仍是</strong> <code>MenuItemSub</code> 递归 <code>ElSubMenu</code>（分组只吃掉一层，见下）</td></tr><tr><td>子项可见性</td><td>需点击父级才展开</td><td>常驻全展开</td></tr></tbody></table><p><strong>分组只吃掉一层——三级菜单是混合渲染。</strong> 分组标题是「视觉聚类」而非「层级实体」，一层标题下不能再嵌一层标题（EP / AntD / shadcn 皆如此）。因此 L1 降格为分组标题后，L2 若仍有 <code>children</code>，只能继续用 <code>ElSubMenu</code> 手风琴。<code>apps/reference/src/router/modules/test.ts</code> 实测存在三级嵌套，分组形态下就会呈现「分组标题 + 组内手风琴」的混合形态，这是设计内行为，非缺陷。</p><p><strong>选型判据</strong>：叶子总量小（经验值 ≤ 25）且层级浅 → 分组（零点击可见全部导航，无手风琴的「东西藏哪了」认知负担）；量大或层级深 → 树形（否则全展开变成长滚动条）。</p><p><strong>视觉不自造</strong>：分组标题吃 EP 原生皮肤（<code>el-menu-item-group__title</code> = <code>font-size:12px</code> + <code>--el-text-color-secondary</code>）；需微调只走主题 var（规则 14），[MUST NOT] 写死颜色。</p><h2 id="徽标-badge" tabindex="-1">徽标（badge） <a class="header-anchor" href="#徽标-badge" aria-label="Permalink to &quot;徽标（badge）&quot;">​</a></h2><p>每个渲染出 <code>menu.path</code> 的位置——L1 叶子、L1 分组标题（分组形态）、递归下去的 ElSubMenu 标题与叶子（经 MenuItemSub）——都以 <strong><code>path</code> 为 key</strong> 查 <code>bridge.badge</code>，命中即渲染绝对定位角标（不改变宿主尺寸）。</p><ul><li><strong>零配置</strong>：菜单数据不用加任何字段；未命中不渲染，对既有菜单零影响。</li><li><strong>不压字、不改尺寸</strong>：角标绝对定位（内部包 ElBadge），跟在标题右侧、不覆盖任何字，且<strong>角标的出现不改变菜单项尺寸</strong>（实测有标/无标逐项宽度差 0）。</li><li><strong>不聚合</strong>：MenuTree [MUST NOT] 把子项的标上卷到父级，父级只显示注册表里挂在它自己 path 上的 entry。</li></ul><p>契约（标记类型 / <code>expireAt</code> 失效 / 已知限制）见 <a href="/done-coding-showcase/docs/core/src/bridge/docs/README.html">bridge 文档 · 徽标注册表</a>。</p><h2 id="快速上手-最小可用" tabindex="-1">快速上手（最小可用） <a class="header-anchor" href="#快速上手-最小可用" aria-label="Permalink to &quot;快速上手（最小可用）&quot;">​</a></h2><p>必填只有 <code>menus</code> + <code>menuFlatList</code>——默认 ElMenu 主题、无路由联动、无选中收合：</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">MenuTree</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :menus</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;menus&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :menuFlatList</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;menuFlatList&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p><strong>要点</strong>：</p><ul><li><code>menus</code> 必填：树形菜单数据；含 <code>children</code> 的节点递归出 <code>ElSubMenu</code></li><li><code>menuFlatList</code> 必填：拍平列表，autoClose 时沿 <code>parentPath</code> 算父链</li><li>菜单数据契约（范式 <code>apps/reference/src/router/modules/test.ts</code>）：<code>meta.menu</code> 的 <code>show</code> / <code>icon</code> / <code>sort</code> 驱动渲染与排序；<code>/menu/showcase/page1|page3|page2</code> 三级嵌套演示递归子菜单，<code>sort</code> 1/2/3 演示排序</li></ul><h2 id="能力边界-按需使用" tabindex="-1">能力边界 / 按需使用 <a class="header-anchor" href="#能力边界-按需使用" aria-label="Permalink to &quot;能力边界 / 按需使用&quot;">​</a></h2><ul><li><strong><code>routerMode</code>：默认关即够用。</strong> 仅当菜单项与路由 path 联动高亮才开——开启后 <code>defaultActive</code> 自动取 <code>route.path</code>（useRoute）+ ElMenu <code>:router</code> 同步开启；注意依赖 vue-router 上下文。</li><li><strong><code>autoClose</code>：默认关即够用。</strong> 仅当「选中一项后收合其它展开子菜单」才开——父链沿 <code>menuFlatList</code> 的 <code>parentPath</code> 递归计算，数据缺失时路径链断裂、收合不全。</li><li><strong><code>collapse</code>：默认不折叠即够用。</strong> 仅当侧栏折叠态需要同步收起菜单才传（透传 ElMenu）。</li><li><strong><code>groupMode</code>：默认关（树形）即够用。</strong> 仅当菜单量小 / 层级浅、要求全展开常驻导航才开。⚠️ <strong>与 <code>collapse</code> 互斥</strong>：分组形态的前提就是「常驻全展开」，两者同时为 true 无意义且 EP 折叠态对 <code>el-menu-item-group</code> 支持不全（EP 的 <code>--collapse</code> 规则既没隐藏 <code>el-menu-item-group__title</code>，也漏掉了 <code>&gt; .el-menu-item-group &gt; ul &gt; .el-menu-item</code> 的「藏文字 + 图标居中」，会溢出窄栏）。消费方 [MUST NOT] 同开两者；<code>AppSidebar</code> 已在内部保证互斥（见其文档）。</li><li><strong>颜色 attrs（<code>background-color</code> / <code>text-color</code> / <code>active-text-color</code> 等）：默认 ElMenu 主题即够用。</strong> 仅当需贴合页面主题配色才显式传。</li><li><strong>完整能力演示</strong>（生产级驱动点 = AppSidebar 内部接线，含折叠 + 路由联动 + 主题配色）：<code>packages/core/src/components/app-layout/AppSidebar.vue</code>——能力展示，非推荐默认。</li></ul><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><blockquote><p>⚠️ API 以 types.ts 与组件源码为真相源；与文档冲突时以源码为准。</p></blockquote><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>name</th><th>type</th><th>默认</th><th>语义</th></tr></thead><tbody><tr><td><code>menus</code></td><td><code>RouteMetaResolveRaw[]</code>（必填）</td><td>—</td><td>树形菜单数据；含 children 的节点递归出 ElSubMenu</td></tr><tr><td><code>menuFlatList</code></td><td><code>RouteMetaResolveRaw[]</code>（必填）</td><td>—</td><td>拍平列表，autoClose 时沿 parentPath 算父链</td></tr><tr><td><code>routerMode?</code></td><td><code>boolean</code></td><td>未设</td><td>路由模式：true 时 defaultActive 取 route.path（useRoute）+ ElMenu :router 开启</td></tr><tr><td><code>collapse?</code></td><td><code>boolean</code></td><td>未设</td><td>折叠态透传 ElMenu</td></tr><tr><td><code>autoClose?</code></td><td><code>boolean</code></td><td>未设</td><td>选中一项后关闭其它展开的 ElSubMenu</td></tr><tr><td><code>groupMode?</code></td><td><code>boolean</code></td><td><code>false</code></td><td>分组形态：L1 有子项时渲染 <code>ElMenuItemGroup</code> 分组标题（不可点 / 不折叠）替代 <code>ElSubMenu</code>；L2+ 仍走 ElSubMenu。与 <code>collapse</code> 互斥</td></tr></tbody></table><p>其余 attrs（<code>background-color</code> / <code>text-color</code> / <code>active-text-color</code> 等 ElMenu props）整包透传。</p><h3 id="emits" tabindex="-1">Emits <a class="header-anchor" href="#emits" aria-label="Permalink to &quot;Emits&quot;">​</a></h3><p>无显式 defineEmits。模板 <code>v-bind=&quot;attrs&quot;</code> 先展开、<code>@select</code> 后声明——外部 <code>onSelect</code> 无法覆盖内部 autoClose 逻辑（推断标注）。</p><h3 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h3><p>无（ElMenu default slot 被 menus v-for 占用）。</p><h3 id="expose" tabindex="-1">Expose <a class="header-anchor" href="#expose" aria-label="Permalink to &quot;Expose&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>参数</th><th>语义</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>index: string</code></td><td>打开指定菜单（代理 ElMenu 同名方法）</td></tr><tr><td><code>close</code></td><td><code>index: string</code></td><td>关闭指定菜单（代理 ElMenu 同名方法）</td></tr></tbody></table><h2 id="反模式-注意" tabindex="-1">反模式 / 注意 <a class="header-anchor" href="#反模式-注意" aria-label="Permalink to &quot;反模式 / 注意&quot;">​</a></h2><ul><li><strong><code>/menu/showcase/Page1/2/3</code> 当用法示范</strong>：它们是菜单渲染出的叶子路由页；MenuTree 的真实消费方是 AppSidebar</li><li><strong>autoClose 缺 parentPath 数据</strong>：父链沿 <code>parentPath</code> 递归计算，数据缺失时路径链断裂、收合不全</li><li><strong>想覆盖内部 @select</strong>：<code>v-bind=&quot;attrs&quot;</code> 展开在前、<code>@select</code> 声明在后，外部 <code>onSelect</code> 无法覆盖内部 autoClose 逻辑（推断标注）</li><li><strong>依赖 vue-router 上下文</strong>：routerMode 使用 <code>useRoute</code>，组件须在安装 vue-router 的上下文中使用</li><li><strong><code>groupMode</code> + <code>collapse</code> 同开</strong>：EP 折叠态不支持 <code>el-menu-item-group</code>（标题不隐藏 + 组内叶子不居中），窄栏会溢出错乱；两者语义本身也互斥</li><li><strong>指望 <code>groupMode</code> 把整棵树拍平</strong>：它只把 L1 降为分组标题，L2+ 仍是手风琴；要全平请先把菜单数据本身收敛到两层</li><li><strong><code>open</code> / <code>close</code> expose 在分组形态下对 L1 无效</strong>：L1 已不是 <code>ElSubMenu</code>（无 index、无展开态），expose 仅对组内仍为 ElSubMenu 的 L2+ 节点有效</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>内部递归：<code>MenuItemSub</code>（menu 族）</li><li>消费方：<code>AppSidebar</code>（app-layout 族）</li><li>数据契约：<code>RouteMetaResolveRaw</code>（@/types）、<code>apps/reference/src/router/modules/test.ts</code>（meta.menu show / icon / sort）</li></ul>',35)])])}const g=o(a,[["render",r]]);export{h as __pageData,g as default};
